import{_ as i,C as r,o as t,c as s,a0 as a,b as c,w as o,a as d,E as l,a1 as u}from"./chunks/framework.DYS8d9tm.js";const _=JSON.parse('{"title":"Technical Specification: Mutual Fund CAS & AMC Statement Ingestion","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/cas_ingestion.md","filePath":"technical/data ingestion/cas_ingestion.md"}'),h={name:"technical/data ingestion/cas_ingestion.md"};function p(g,e,m,f,A,S){const n=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="technical-specification-mutual-fund-cas-amc-statement-ingestion" tabindex="-1">Technical Specification: Mutual Fund CAS &amp; AMC Statement Ingestion <a class="header-anchor" href="#technical-specification-mutual-fund-cas-amc-statement-ingestion" aria-label="Permalink to &quot;Technical Specification: Mutual Fund CAS &amp; AMC Statement Ingestion&quot;">​</a></h1><p><strong>Document Version:</strong> 1.1.0<br><strong>Status:</strong> Active / Technical Reference<br><strong>Owner:</strong> Investment Engineering</p><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Mutual Fund ingestion pipeline processes two distinct categories of investment documents in the WealthFam ecosystem:</p><ol><li><strong>Consolidated Account Statements (CAS)</strong>: Periodic aggregate statements from <strong>CAMS</strong>, <strong>KFintech</strong>, <strong>CDSL</strong> (<code>eCAS@cdslstatement.com</code>, <code>cdslindia</code>, <code>&quot;Central Depository Services&quot;</code>), and <strong>NSDL</strong> containing high-density portfolio summaries across multiple folios, fund houses, and depositories.</li><li><strong>Individual AMC Statements of Account (SOA)</strong>: Folio-level statements downloaded directly from individual AMC websites or mobile apps (e.g., Nippon India MF, ICICI Prudential MF, SBI MF, Axis MF, Mirae Asset).</li></ol><p>This document specifies the forensic extraction, fallback hierarchy, and ledger deduplication logic.</p><h2 id="_2-ingestion-flow" tabindex="-1">2. Ingestion Flow <a class="header-anchor" href="#_2-ingestion-flow" aria-label="Permalink to &quot;2. Ingestion Flow&quot;">​</a></h2>',7)),(t(),c(u,null,{default:o(()=>[l(n,{id:"mermaid-30",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20%22Capture%22%0A%20%20%20%20%20%20%20%20MAIL%5BIMAP%20Sync%20Engine%5D%20--%3E%7CFind%20CAMS%2FKFintech%2FAMC%7C%20PDF%5BEncrypted%2FPlain%20PDF%5D%0A%20%20%20%20%20%20%20%20UPLOAD%5BManual%20Upload%5D%20--%3E%20PDF%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Forensic%20Extraction%20%26%20Dispatch%22%0A%20%20%20%20%20%20%20%20PDF%20--%3E%7CPWD%20Unlock%7C%20PARSER_MS%5BParser%20Microservice%20%3A8001%5D%0A%20%20%20%20%20%20%20%20PARSER_MS%20--%3E%7CStandard%20CAS%20Detection%7C%20CAS_LIB%5Bcasparser%20Library%5D%0A%20%20%20%20%20%20%20%20PARSER_MS%20--%3E%7CNon-CAS%20%2F%20Validation%20Fallback%7C%20AMC_DISPATCH%7BAmcSoaParser%7D%0A%20%20%20%20%20%20%20%20AMC_DISPATCH%20--%3E%7CKFintech%20Layout%7C%20KFIN%5BKfintechSoaParser%5D%0A%20%20%20%20%20%20%20%20AMC_DISPATCH%20--%3E%7CCAMS%20Layout%7C%20CAMS%5BCamsSoaParser%5D%0A%20%20%20%20%20%20%20%20CAS_LIB%20%26%20KFIN%20%26%20CAMS%20--%3E%20NORMALIZED%5BStandardized%20Transaction%20Dict%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Ledger%20Reconciliation%20%26%20Deduplication%22%0A%20%20%20%20%20%20%20%20NORMALIZED%20--%3E%20SMART_USER%5BSmart%20User%20Resolution%3A%20Folio%20%2F%20Name%5D%0A%20%20%20%20%20%20%20%20SMART_USER%20--%3E%20FOLIO_NORM%5BFolio%20Normalization%3A%20Strip%20Check-Digits%5D%0A%20%20%20%20%20%20%20%20FOLIO_NORM%20--%3E%20DEDUP%5BTenant-Wide%20Duplicate%20Detection%5D%0A%20%20%20%20%20%20%20%20DEDUP%20--%3E%7CFlag%20Duplicate%7C%20STMT_TXN%5BStatementTransaction%3A%20is_duplicate%5D%0A%20%20%20%20%20%20%20%20STMT_TXN%20--%3E%7CReconciliation%7C%20ORDERS%5B(MutualFundOrder%20%26%20Holdings)%5D%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="_3-data-extraction-logic" tabindex="-1">3. Data Extraction Logic <a class="header-anchor" href="#_3-data-extraction-logic" aria-label="Permalink to &quot;3. Data Extraction Logic&quot;">​</a></h2><h3 id="_3-1-pdf-decryption-vault-storage-cdsl-hardening" tabindex="-1">3.1 PDF Decryption, Vault Storage &amp; CDSL Hardening <a class="header-anchor" href="#_3-1-pdf-decryption-vault-storage-cdsl-hardening" aria-label="Permalink to &quot;3.1 PDF Decryption, Vault Storage &amp; CDSL Hardening&quot;">​</a></h3><p>CAS and AMC files are secured with a combination of PAN and Date of Birth (DOB) or pure uppercase/lowercase PAN (or PIN code / Folio number as fallback).</p><ul><li><strong>Auto-Trial &amp; Cache</strong>: The system attempts decryption using <code>StatementPasswordService</code> and user profile metadata (PAN/DOB) before marking the statement <code>PENDING</code> for manual input.</li><li><strong>Persistent Vault Storage &amp; Auto-Unlock</strong>: Unlocked PDFs are stored persistently under <code>VAULT_STORAGE_PATH</code> (<code>/data/vault</code>) with SHA-256 deduplication preventing duplicate version growth across retries. Legacy encrypted statement PDFs on disk are automatically unlocked in-place upon access via <code>VaultService.ensure_unlocked_pdf</code>.</li><li><strong><code>casparser</code> CDSL &amp; Header-Window Patching</strong>: <code>Parser/core/utils.py</code> (<code>patch_casparser()</code>) idempotently patches <strong>both</strong> <code>casparser.process.process_cas_text</code> and the imported <code>casparser.parsers.process_cas_text</code> binding used by <code>read_cas_pdf()</code> to route <code>FileType.CDSL</code> alongside <code>FileType.NSDL</code>, widen CAS type/header detection to <code>text[:5000]</code>, and retry <code>HeaderParseError</code> on cover-page headers past character 1000.</li><li><strong>Tightened Handler Routing</strong>: <code>MutualFundCasHandler.can_handle()</code> applies word-bounded regex (<code>r&#39;\\bcas\\b&#39;</code>, <code>r&#39;\\bcams\\b&#39;</code>, <code>r&#39;\\bkfintech\\b&#39;</code>, <code>r&#39;\\bsoa\\b&#39;</code>, <code>r&#39;statement\\s*of\\s*account&#39;</code>, <code>r&#39;consolidated\\s*account\\s*statement&#39;</code>) and explicit negative checks for bank/credit card/cashback files.</li><li><strong>Structured Error Visibility</strong>: Non-200 responses from <code>/v1/ingest/cas</code> are logged with full tracebacks and returned as structured error dictionaries (<code>status</code>, <code>message</code>, <code>detail</code>), preventing silent <code>None</code> drops and generic &quot;Unknown Error&quot; reports.</li></ul><h3 id="_3-2-individual-amc-statement-of-account-soa-support" tabindex="-1">3.2 Individual AMC Statement of Account (SOA) Support <a class="header-anchor" href="#_3-2-individual-amc-statement-of-account-soa-support" aria-label="Permalink to &quot;3.2 Individual AMC Statement of Account (SOA) Support&quot;">​</a></h3><p>Single-fund statements downloaded directly from fund portals lack the SEBI-mandated investor block expected by <code>casparser</code>, causing Pydantic validation errors (<code>investor_info Input should be a valid dictionary</code>). To support direct AMC statement uploads without forcing users to request CAMS/KFintech CAS mailbacks:</p><ul><li><strong><code>AmcSoaParser</code> Fallback</strong>: If <code>casparser</code> fails or if the document is recognized as a single-fund statement, execution delegates directly to <code>AmcSoaParser</code>.</li><li><strong>Two RTA Layout Engines</strong>: <ol><li><strong><code>KfintechSoaParser</code></strong>: Parses KFintech-serviced AMCs (Nippon India, Axis MF, Mirae Asset, UTI MF, Motilal Oswal, Quant, etc.), extracting the 7-column table layout:<br> $$\\text{NAV Date} \\quad\\vert\\quad \\text{Transaction Type} \\quad\\vert\\quad \\text{Amount} \\quad\\vert\\quad \\text{Revised Cost} \\quad\\vert\\quad \\text{NAV} \\quad\\vert\\quad \\text{Units} \\quad\\vert\\quad \\text{Balance Units}$$</li><li><strong><code>CamsSoaParser</code></strong>: Parses CAMS-serviced AMCs (HDFC MF, ICICI Prudential, SBI MF, Kotak Mahindra, DSP, etc.), extracting the CAMS single-folio table layout:<br> $$\\text{Date} \\quad\\vert\\quad \\text{Description} \\quad\\vert\\quad \\text{Amount} \\quad\\vert\\quad \\text{Units} \\quad\\vert\\quad \\text{Price/NAV} \\quad\\vert\\quad \\text{Balance Units}$$</li></ol></li><li><strong>Canonical Normalization</strong>: Extracts Folio, Scheme Name, ISIN (regex <code>INF[A-Z0-9]{9}</code>), and exact transaction rows with high-precision Decimal amounts.</li></ul><h3 id="_3-3-smart-target-user-resolution" tabindex="-1">3.3 Smart Target User Resolution <a class="header-anchor" href="#_3-3-smart-target-user-resolution" aria-label="Permalink to &quot;3.3 Smart Target User Resolution&quot;">​</a></h3><p>Statements received via email sync often arrive on behalf of different family members within the same household:</p><ol><li><strong>Existing Folio Ownership</strong>: In <code>cas_handler.py</code>, the system checks whether active <code>MutualFundOrder</code> records for the extracted folio already exist under a specific family member in the tenant. If found, all transactions are attributed to that user.</li><li><strong>Context Matching</strong>: If the folio is brand new, the system scans the statement text and email body for user full names and email addresses.</li><li><strong>Owner Fallback</strong>: Defaults to the tenant owner only if no user match is found.</li></ol><hr><h2 id="_4-deduplication-strategy" tabindex="-1">4. Deduplication Strategy <a class="header-anchor" href="#_4-deduplication-strategy" aria-label="Permalink to &quot;4. Deduplication Strategy&quot;">​</a></h2><p>Investment statements are cumulative (often spanning 6–36 months of transaction history). To prevent duplicate orders and doubled unit counts:</p><ol><li><p><strong>Folio Normalization (<code>_normalize_folio</code>)</strong>:</p><ul><li>CAMS/KFintech CAS files format folios with check-digit or sub-account suffixes (e.g., <code>&#39;477326559824 / 0&#39;</code>, <code>&#39;12345678 / 90&#39;</code>), whereas direct AMC statements omit the suffix (<code>&#39;477326559824&#39;</code>).</li><li>The deduplicator normalizes folios via <code>re.sub(r&#39;\\s*/\\s*0*$&#39;, &#39;&#39;, folio)</code> and collapses whitespace before equality checks, ensuring CAS imports and AMC SOA imports match cleanly.</li></ul></li><li><p><strong>Tenant-Level Multi-Member Deduplication</strong>:</p><ul><li>A mutual fund folio number is globally unique to an individual account holder.</li><li><code>MutualFundService.check_duplicates</code> checks candidate active orders across the entire household/tenant for matching <code>(scheme_code, date, units, amount, normalized_folio)</code>.</li><li>Matching orders are flagged with <code>is_duplicate: true</code> (pre-unselected in the UI with a <code>Duplicate</code> badge).</li><li>If the statement transaction was initially unassigned, it automatically adopts the existing order&#39;s <code>user_id</code>.</li></ul></li><li><p><strong>Synthesized Balance Deduplication</strong>:</p><ul><li>For summary CAS statements lacking detailed transaction history, synthesized balance records are checked against existing <code>MutualFundHolding</code> units. If existing holding units $\\ge$ incoming units, the synthesized transaction is flagged duplicate to prevent unit inflation.</li></ul></li><li><p><strong>External Reference &amp; Idempotency</strong>:</p><ul><li>When present, normalized bank UTR / external reference IDs prevent duplicate order insertion during ledger reconciliation.</li></ul></li></ol><hr><h2 id="_5-the-ironclad-ledger-standard" tabindex="-1">5. The &quot;Ironclad&quot; Ledger Standard <a class="header-anchor" href="#_5-the-ironclad-ledger-standard" aria-label="Permalink to &quot;5. The &quot;Ironclad&quot; Ledger Standard&quot;">​</a></h2><p>WealthFam enforces a non-destructive, &quot;In-Place Update&quot; policy for mutual fund data.</p><h3 id="_5-1-in-place-updates-vs-destructive-sync" tabindex="-1">5.1 In-Place Updates vs. Destructive Sync <a class="header-anchor" href="#_5-1-in-place-updates-vs-destructive-sync" aria-label="Permalink to &quot;5.1 In-Place Updates vs. Destructive Sync&quot;">​</a></h3><ul><li><strong>Standard Sync</strong>: Traditional apps delete all previous transactions and re-import the CAS. This breaks UUID links to goals, notes, and historical XIRR snapshots.</li><li><strong>WealthFam Sync</strong>: We perform a <strong>Surgical Diff</strong>. Only new transactions are appended, and existing transactions are updated only if their fundamental metadata (Units/NAV) has changed.</li></ul><h3 id="_5-2-precision-calculation" tabindex="-1">5.2 Precision Calculation <a class="header-anchor" href="#_5-2-precision-calculation" aria-label="Permalink to &quot;5.2 Precision Calculation&quot;">​</a></h3><p>Every calculation in the investment ledger uses the <code>Decimal</code> library to 6+ decimal places.</p><ul><li><strong>Zero Drift</strong>: This ensures that &quot;Units × NAV&quot; always matches the &quot;Current Value&quot; exactly, preventing the cent-level rounding errors common in mobile apps.</li></ul><hr><h2 id="_6-xirr-performance-tracking" tabindex="-1">6. XIRR &amp; Performance Tracking <a class="header-anchor" href="#_6-xirr-performance-tracking" aria-label="Permalink to &quot;6. XIRR &amp; Performance Tracking&quot;">​</a></h2><p>XIRR (Extended Internal Rate of Return) is calculated per fund and per folio.</p><ul><li><strong>Cash Flow Verification</strong>: Returns are only calculated on &quot;Confirmed&quot; cash flows (Buy/Sell/Dividend).</li><li><strong>Pending Status</strong>: Transactions from a CAS that do not match existing bank withdrawals are flagged for &quot;Cash Flow Reconciliation&quot; in the UI.</li></ul>',26))])}const b=i(h,[["render",p]]);export{_ as __pageData,b as default};
